//! A least-recently-used cache with a fixed capacity.

use std::collections::HashMap;
use std::hash::Hash;

/// A map that holds at most `capacity` entries. When a new key is inserted into a full cache, the least recently
/// used entry is evicted. `get` and `put` count as uses; `peek` does not.
///
/// All operations except `iter` and `resize` are O(1) on average.
///
/// Internally this is a hash map from keys to node indices plus a doubly linked list of nodes (also indexed)
/// that keeps entries in recency order: the head is the most recently used entry, the tail the least recently
/// used one. Node indices are recycled through a free list, so every operation is O(1) on average without any
/// linear scans.
pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    free: Vec<usize>,
    head: Option<usize>,
    tail: Option<usize>,
    capacity: usize,
}

struct Node<K, V> {
    key: Option<K>,
    value: Option<V>,
    prev: Option<usize>,
    next: Option<usize>,
}

/// Iterator over the cache entries, from the most recently used to the least recently used one.
struct Iter<'a, K, V> {
    nodes: &'a [Node<K, V>],
    cur: Option<usize>,
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        let idx = self.cur?;
        let node = &self.nodes[idx];
        let key = node.key.as_ref()?;
        let value = node.value.as_ref()?;
        self.cur = node.next;
        Some((key, value))
    }
}

impl<K: Hash + Eq + Clone, V> LruCache<K, V> {
    /// Panics if `capacity` is 0.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be greater than zero");
        Self {
            map: HashMap::new(),
            nodes: Vec::new(),
            free: Vec::new(),
            head: None,
            tail: None,
            capacity,
        }
    }

    /// Returns the value and marks the entry as most recently used.
    pub fn get(&mut self, key: &K) -> Option<&V> {
        let node = *self.map.get(key)?;
        self.move_to_front(node);
        self.nodes[node]
            .value
            .as_ref()
            .expect("map and linked list stay in sync")
    }

    /// Like `get`, but returns a mutable reference.
    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        let node = *self.map.get(key)?;
        self.move_to_front(node);
        self.nodes[node]
            .value
            .as_mut()
            .expect("map and linked list stay in sync")
    }

    /// Returns the value without changing the order.
    pub fn peek(&self, key: &K) -> Option<&V> {
        self.map
            .get(key)
            .and_then(|&node| self.nodes[node].value.as_ref())
    }

    /// Inserts or replaces a value and marks it as most recently used. Returns the old value if the key was
    /// present. If the key is new and the cache is full, the least recently used entry is evicted first.
    pub fn put(&mut self, key: K, value: V) -> Option<V> {
        if let Some(&node) = self.map.get(&key) {
            let old = self
                .nodes[node]
                .value
                .take()
                .expect("map and linked list stay in sync");
            self.nodes[node].value = Some(value);
            self.move_to_front(node);
            return Some(old);
        }
        if self.map.len() >= self.capacity {
            self.evict_lru();
        }
        let node = self.alloc_node(key.clone(), value);
        self.map.insert(key, node);
        self.link_front(node);
        None
    }

    /// Removes an entry and returns its value.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        let node = *self.map.remove(key)?;
        self.unlink(node);
        let value = self
            .nodes[node]
            .value
            .take()
            .expect("map and linked list stay in sync");
        self.free_node(node);
        Some(value)
    }

    /// Removes and returns the least recently used entry.
    pub fn pop_lru(&mut self) -> Option<(K, V)> {
        let tail = self.tail?;
        let key = self
            .nodes[tail]
            .key
            .take()
            .expect("map and linked list stay in sync");
        let value = self
            .nodes[tail]
            .value
            .take()
            .expect("map and linked list stay in sync");
        self.unlink(tail);
        self.free_node(tail);
        self.map.remove(&key);
        Some((key, value))
    }

    pub fn contains(&self, key: &K) -> bool {
        self.map.contains_key(key)
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }

    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }

    pub fn capacity(&self) -> usize {
        self.capacity
    }

    /// Changes the capacity, evicting least recently used entries until `len() <= capacity`. Panics if
    /// `capacity` is 0.
    pub fn resize(&mut self, capacity: usize) {
        assert!(capacity > 0, "capacity must be greater than zero");
        self.capacity = capacity;
        while self.map.len() > capacity {
            self.evict_lru();
        }
    }

    /// Removes every entry.
    pub fn clear(&mut self) {
        self.map.clear();
        self.nodes.clear();
        self.free.clear();
        self.head = None;
        self.tail = None;
    }

    /// Iterates from the most recently used entry to the least recently used one.
    pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> + '_ {
        Iter {
            nodes: &self.nodes,
            cur: self.head,
        }
    }

    /// Allocates a node, reusing a freed one if possible, and stores the entry in it.
    fn alloc_node(&mut self, key: K, value: V) -> usize {
        match self.free.pop() {
            Some(idx) => {
                self.nodes[idx].key = Some(key);
                self.nodes[idx].value = Some(value);
                self.nodes[idx].prev = None;
                self.nodes[idx].next = None;
                idx
            }
            None => {
                let idx = self.nodes.len();
                self.nodes.push(Node {
                    key: Some(key),
                    value: Some(value),
                    prev: None,
                    next: None,
                });
                idx
            }
        }
    }

    /// Drops a node's contents and returns it to the free list.
    fn free_node(&mut self, idx: usize) {
        self.nodes[idx].key = None;
        self.nodes[idx].value = None;
        self.nodes[idx].prev = None;
        self.nodes[idx].next = None;
        self.free.push(idx);
    }

    /// Unlinks a node from the list, updating the head and tail as needed.
    fn unlink(&mut self, idx: usize) {
        let prev = self.nodes[idx].prev.take();
        let next = self.nodes[idx].next.take();
        if let Some(prev) = prev {
            self.nodes[prev].next = next;
        }
        if let Some(next) = next {
            self.nodes[next].prev = prev;
        }
        if self.head == Some(idx) {
            self.head = next;
        }
        if self.tail == Some(idx) {
            self.tail = prev;
        }
    }

    /// Links a detached node as the new head (most recently used).
    fn link_front(&mut self, idx: usize) {
        let head = self.head;
        self.nodes[idx].prev = None;
        self.nodes[idx].next = head;
        if let Some(head) = head {
            self.nodes[head].prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }

    /// Moves a node to the front of the list, marking it as most recently used.
    fn move_to_front(&mut self, idx: usize) {
        if self.head != Some(idx) {
            self.unlink(idx);
            self.link_front(idx);
        }
    }

    /// Removes the least recently used entry from the map and the list.
    fn evict_lru(&mut self) {
        let Some(tail) = self.tail else {
            return;
        };
        let key = self
            .nodes[tail]
            .key
            .take()
            .expect("map and linked list stay in sync");
        self.unlink(tail);
        self.free_node(tail);
        self.map.remove(&key);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_cache_is_empty() {
        let c: LruCache<u32, u32> = LruCache::new(4);
