    #[test]
    fn clear_removes_all_entries() {
        let mut c: LruCache<u32, u32> = LruCache::new(2);
        c.put(1, 10);
        c.put(2, 20);
        c.clear();
        assert!(c.is_empty());
        assert_eq!(c.iter().count(), 0);
        assert_eq!(c.pop_lru(), None);
        // The cache is fully usable afterwards.
        c.put(3, 30);
        c.put(4, 40);
        c.put(5, 50);
        assert_eq!(c.get(&3), None);
        assert_eq!(c.get(&4), Some(&40));
        assert_eq!(c.get(&5), Some(&50));
    }

    #[test]
    fn works_with_non_copy_values() {
        let mut c: LruCache<&'static str, String> = LruCache::new(2);
        c.put("a", "one".to_string());
        c.put("b", "two".to_string());
        assert_eq!(c.put("a", "uno".to_string()), Some("one".to_string()));
        c.put("c", "three".to_string()); // evicts "b"
        assert_eq!(c.get("b"), None);
        assert_eq!(c.peek("c"), Some(&"three".to_string()));
        assert_eq!(c.pop_lru(), Some(("a".to_owned(), "uno".to_string())));
    }

    #[test]
    fn repeated_eviction_and_reinsertion() {
        // Cycles of eviction, removal, and reinsertion must not corrupt the list.
        let mut c: LruCache<u32, u32> = LruCache::new(2);
        for i in 0..20 {
            c.put(i % 3, i);
            if i % 4 == 0 {
                let _ = c.remove(&0);
            }
            if i % 5 == 0 {
                let _ = c.pop_lru();
            }
            assert_eq!(c.iter().count(), c.len());
            assert!(c.len() <= c.capacity());
        }
        let items: Vec<(u32, u32)> = c.iter().map(|(k, v)| (**k, **v)).collect();
        // Every key maps to the same value it was last inserted with.
        for (k, v) in &items {
            assert_eq!(*v % 3, *k % 3);
        }
    }

    #[test]
    fn fuzz_against_reference_model() {
        // Reference model: a Vec of (key, value) where index 0 is the least recently used entry.
        const CAP: usize = 3;
        let mut model: Vec<(u32, u32)> = Vec::new();
        let mut cache: LruCache<u32, u32> = LruCache::new(CAP);
        let mut seed: u64 = 0x9e37_79b9_7f4a_7c15;
        let mut rnd = || {
            seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            (seed >> 33) as u32
        };
        for _ in 0..20_000 {
            let k = rnd() % 8;
            match rnd() % 6 {
                0 | 1 => {
                    // put
                    let v = k * 7 + rnd() % 100;
                    if let Some(pos) = model.iter().position(|(mk, _)| *mk == k) {
                        model.remove(pos);
                    } else if model.len() == CAP {
                        model.remove(0);
                    }
                    model.push((k, v));
                    cache.put(k, v);
                }
                2 => {
                    // get
                    if let Some(pos) = model.iter().position(|(mk, _)| *mk == k) {
                        model.push(model.remove(pos));
                    }
                    let want = model.last().filter(|(mk, _)| *mk == k).map(|(_, v)| *v);
                    assert_eq!(cache.get(&k).map(|v| *v), want);
                }
                3 => {
                    // peek
                    let want = model.iter().rev().find(|(mk, _)| *mk == k).map(|(_, v)| *v);
                    assert_eq!(cache.peek(&k), want);
                }
                4 => {
                    // remove
                    let want = model
                        .iter()
                        .position(|(mk, _)| *mk == k)
                        .map(|pos| model.remove(pos).1);
                    assert_eq!(cache.remove(&k), want);
                }
                5 => {
                    if rnd() % 4 == 0 {
                        // pop_lru
                        let want = model.first().map(|(mk, v)| (*mk, *v)).map(|entry| {
                            model.remove(0);
                            entry
                        });
                        assert_eq!(cache.pop_lru(), want);
                    } else {
                        // resize
                        let new_cap = 1 + (rnd() % 5) as usize;
                        while model.len() > new_cap {
                            model.remove(0);
                        }
                        cache.resize(new_cap);
                    }
                }
                _ => unreachable!(),
            }
            assert_eq!(cache.len(), model.len());
            let got: Vec<(u32, u32)> = cache.iter().map(|(k, v)| (**k, **v)).collect();
            assert_eq!(got, model.iter().rev().cloned().collect());
        }
    }
}

